#include "SongStudio.h"
#include <iostream>
#include <stdexcept>
static void check(bool ok,const char* text){if(!ok)throw std::runtime_error(text);}
static bool near(float a,float b){return std::abs(a-b)<.000002f;}
int main(){const auto root=juce::File::getSpecialLocation(juce::File::tempDirectory).getChildFile("idw-sections-"+juce::Uuid().toString());root.createDirectory();try{
    SongStudio song;song.prepare(48000);auto pattern=song.pattern();pattern.bpm=137;pattern.bars=2;pattern.rows.fill(0);song.setPattern(pattern);const int frames=(int)pattern.samples(48000),begin=(int)std::ceil(240.*48000/137),length=frames-begin;
    check(song.start(true),"Recording fixture");juce::AudioBuffer<float> input(2,frames);for(int i=0;i<frames;++i)for(int ch=0;ch<2;++ch)input.setSample(ch,i,.1f+(i%2000)/20000.f);song.process(input);song.stop();
    const auto old=root.getChildFile("old.idwsong");check(song.save(old).wasOk(),"Old-format save");
    check(!song.setSection(0,{"",1,1})&&!song.setSection(0,{"Bad",2,1})&&!song.setSection(0,{"Bad",1,65})&&!song.setSection(2,{"Bad",1,1}),"Invalid section accepted");
    check(song.setSection(0,{juce::String::fromUTF8("Hook / 夜"),2,2}),"Add section");check(song.playSection(0,false)&&song.songBar()==2,"Play section start/bar");
    juce::AudioBuffer<float> once(2,length+20);once.clear();song.process(once);check(!song.isPlaying(),"One-shot did not stop");for(int i=0;i<length;++i)check(near(once.getSample(0,i),input.getSample(0,begin+i)),"One-shot wrong source");for(int i=length;i<length+20;++i)check(once.getSample(0,i)==0,"One-shot tail not cleared");
    check(song.playSection(0,true)&&song.isLooping(),"Loop start");check(!song.setSection(0,{"Blocked",1,1})&&!song.removeSection(0)&&!song.start(true),"Transport edit protection");
    for(int at=0;at<length*3+71;){const int count=std::min(1031,length*3+71-at);juce::AudioBuffer<float> block(2,count);block.clear();song.process(block);for(int i=0;i<count;++i)check(near(block.getSample(0,i),input.getSample(0,begin+(at+i)%length)),"Loop lost/duplicated samples across blocks");at+=count;}check(song.isLooping(),"Loop stopped unexpectedly");song.stop();
    check(song.setSection(1,{"Verse",1,1})&&song.removeSection(0)&&song.sections()[0].name=="Verse"&&song.undoTrackEdit()&&song.sections().size()==2&&song.redoTrackEdit()&&song.undoTrackEdit(),"Marker undo/redo");
    const auto project=root.getChildFile("sections.idwsong");check(song.save(project).wasOk(),"Section save");auto stream=project.createInputStream();stream->readInt();check(stream->readInt()==6,"Wrong section format");stream.reset();SongStudio restored;restored.prepare(48000);check(restored.load(project).wasOk()&&restored.sections().size()==2&&restored.sections()[0].name==song.sections()[0].name&&!restored.isLooping(),"Section roundtrip");
    std::uint64_t stamp=0;auto snapshot=song.recoverySnapshot(stamp);check(snapshot!=nullptr&&song.removeSection(0)&&snapshot->sections().size()==2,"Section recovery mutated");
    juce::MemoryBlock data;project.loadFileAsData(data);const auto bad=root.getChildFile("bad.idwsong");bad.replaceWithData(data.getData(),data.getSize()-1);check(restored.load(bad).failed()&&restored.sections().size()==2,"Truncated section changed song");juce::MemoryOutputStream invalid;invalid.write(data.getData(),data.getSize()-4);invalid.writeInt(65);bad.replaceWithData(invalid.getData(),invalid.getDataSize());check(restored.load(bad).failed(),"Invalid section range loaded");
    check(restored.playSection(0,true),"Restored loop");restored.stop();const auto wav=root.getChildFile("whole.wav");check(restored.exportWav(wav).wasOk(),"Export after loop");juce::WavAudioFormat format;std::unique_ptr<juce::AudioFormatReader> reader(format.createReaderFor(wav.createInputStream().release(),true));check(reader&&reader->lengthInSamples==frames,"Loop changed export duration");
    pattern.bars=1;check(restored.setPattern(pattern)&&!restored.playSection(0,true)&&restored.sections().size()==2,"Out-of-song section lost or played");pattern.bars=2;pattern.bpm=120;restored.setPattern(pattern);check(restored.playSection(0,false)&&near((float)restored.seconds(),2.f),"Section did not follow BPM");restored.stop();
    check(restored.load(old).wasOk()&&restored.sections().empty(),"Old format kept section markers");check(restored.armLane(2)&&restored.start(true)&&restored.seconds()==0&&!restored.isLooping(),"Recording inherited loop");restored.stop();
    SongStudio rhythm;rhythm.prepare(48000);auto rhythmPattern=rhythm.pattern();rhythmPattern.bpm=137;rhythmPattern.bars=2;rhythm.setPattern(rhythmPattern);rhythm.setMetronomeEnabled(true);check(rhythm.setSection(0,{"Hook",2,2})&&rhythm.playSection(0,true),"Rhythm loop start");juce::AudioBuffer<float> beats(2,length*2);beats.clear();rhythm.process(beats);rhythm.stop();check(beats.getMagnitude(0,length)>0,"Loop rhythm silent");for(int i=0;i<length;++i)check(near(beats.getSample(0,i),beats.getSample(0,length+i)),"Drum/click restart differs across passes");
    SongStudio limited;for(int i=0;i<32;++i)check(limited.setSection(i,{"Section",1,1}),"Section capacity");check(!limited.setSection(32,{"Too many",1,1}),"Section cap exceeded");
    std::cout<<"PASS section one-shot/loop sample boundaries, fractional tempo, transport lock, undo, format6, corrupt load, recovery, full export, BPM changes and recording isolation\n";root.deleteRecursively();return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';root.deleteRecursively();return 1;}}
